// ---------- Harita sonu: kazanma ----------
/* p2m4: üç hedef = üç yıldız (meta.sm[L] bit maskesi): bit0 patron yenildi · bit1 sur hiç %50'nin altına inmedi (S.minGate) · bit2 tekrar/ikinci şans yok (S.retries) */
const popc=b=>{ let t=0; b=(b|0)>>>0; while(b){ t+=b&1; b>>>=1; } return t; };
const STAR_WALL=0.7; /* v44: 2. yıldız: sur hiç %70'in altına inmesin (eski %50: 3★ varsayılandı) */
function starMask(){ return 1|((S.minGate||0)>=STAR_WALL-1e-9?2:0)|((S.retries|0)===0?4:0); }
const smOf=L=>(S.meta&&S.meta.sm&&(+S.meta.sm[L])|0)||0;
const OBJS=[{i:'💀',t:T('Patronu yen','Defeat the boss')},{i:'🧱',t:T("Sur hiç %70'in altına inmesin","Walls never drop below 70%")},{i:'🔁',t:T('Tekrar ya da ikinci şans yok','No retries or second chances')}];
/* p2m4: harita bilgisi (ad, tema, yeni düşman, patron) — harita listesi, ayrıntı satırı ve "sıradaki harita" tanıtımı aynı kaynaktan */
const NEWE={1:['runner','shield'],2:['raider'],3:['wolf','ram'],4:['ram'],5:['archer'],6:['poison'],7:['knight'],8:['pirate'],9:['ice'],10:['knight','ice','poison']};
function mapName(L){ if(L>LEVELS) return ENAME(); const r=(MAPS[L]&&MAPS[L].regs[0])||null; return r&&REG[r]?REG[r].name:T('Orman Kapısı','Forest Gate'); }
function mapIc(L){ if(L>LEVELS) return '♾'; const r=(MAPS[L]&&MAPS[L].regs[0])||null; return (r&&REG_IC[r])||'🌲'; }
function mapJob(L){ const r=(MAPS[L]&&MAPS[L].regs[0])||null; return r&&REG[r]?REG[r].job:T('Odun kes, kule kur','Chop wood, build towers'); }
function mapFoes(L){ return (NEWE[L]||[]).filter(k=>EK[k]).map(k=>`${KIND_IC[k]||''} ${EK[k].name}`).join(', '); }
function mapBoss(L){ return (BOSSES[L]||BOSSES[1]).n; }
function mapTitle(L){ return L>LEVELS?ENAME():T(`${L}. Harita`,`Map ${L}`); }
