  card.innerHTML=`<div class="card result"><div class="bigstars">${[1,2,3].map(i=>`<span class="st${i<=st?' on':''}" style="animation-delay:${0.25+i*0.35}s">★</span>`).join('')}</div><h1>${T(`Gece ${eNight(L,WAVES)} atlatıldı!`,`Night ${eNight(L,WAVES)} survived!`)}</h1><p class="boss">${T(`${bossName()} yenildi`,`${bossName()} defeated`)}</p><p>${T(`Surun en zor anında <b>%${Math.round(S.minGate*100)}</b> canı kaldı.`,`Lowest Wall HP: <b>${Math.round(S.minGate*100)}%</b>.`)}</p><div class="crowns">👑 +<b data-to="${gain}">${fmtN(gain)}</b></div>${endlessWinTxt()}<button id="winNext">${T(`Gece ${eNight(L,WAVES)+1} →`,`Night ${eNight(L,WAVES)+1} →`)}</button><button id="winMap" class="ghost">${T('Krallık','Kingdom')}</button></div>`;
  document.body.appendChild(card); countUp(card,900);
