  card.innerHTML=`<div class="card result fail"><h1>${T('Sur yıkıldı!','The Walls fell!')}</h1><p class="boss">${endless()?`${chapTitle()} · `:''}${T('Kalen yerinde — bu gece baştan başlayacak','Your castle stands — this night starts over')}</p><p class="near">${left<=5?T(`Sadece <b>${left}</b> düşman kalmıştı!`,`Only <b>${left}</b> ${left===1?'enemy':'enemies'} left!`):T(`${n}. gecede <b>${left}</b> düşman kalmıştı.`,`Night ${n}: <b>${left}</b> enemies left.`)}</p>${endless()?`<p class="rec${rec?' new':''}">🏆 ${rec?T(`Yeni rekor! ${S.meta.best}. gece`,`New record! Night ${S.meta.best}`):T(`Rekor: ${S.meta.best||0}. gece`,`Best: Night ${S.meta.best||0}`)}</p>`:`<div class="prog"><i style="width:0%"></i><span>${T(`Harita ilerlemesi: %${pct}`,`Map progress: ${pct}%`)}</span></div>`}<p class="hint">💡 ${failTip()}</p>${ku&&!canRevive?`<p class="hint kh">👑 ${T(`${S.meta.crowns} tacın harcanmayı bekliyor: Krallık'ta kalıcı güç al (Taş Temel sur canını artırır).`,`${S.meta.crowns} crowns unspent: buy a permanent upgrade in the Kingdom (Stone Foundation adds Wall HP).`)}</p>`:''}${paid?`<div class="crowns">${T(`👑 +${paid} taç kazandın`,`👑 +${paid} crown${paid===1?'':'s'} earned`)}</div>`:''}${canRevive?(adRev?'<button id="revive">'+T('📺 İkinci şans (reklam)','📺 Second chance (ad)')+'</button>':'<button id="revive" class="gold prim">'+T('🛡️ İkinci şans','🛡️ Second chance')+'<small>'+T('Sur onarılır, savaş sürer','Walls repaired, keep fighting')+'</small></button>'):''}<div class="brow"><button id="retry"${canRevive&&!adRev?' class="sec"':''}>${T(`Gece ${endless()?eNight(L,n):n}: tekrar dene`,`Retry Night ${endless()?eNight(L,n):n}`)}</button><button id="failMap" class="ghost">${ku?`👑 ${S.meta.crowns} · `:''}${T('Krallık','Kingdom')}</button></div></div>`; if(rec) setTimeout(confetti,300);
