// canlanma reklama değmeli: sur adil seviyeye (patron gecesi tam) döner, düşmanlar yolun gerisine itilir (koçbaşı/patron daha da geriye), 8 sn kalkan sur hasarını keser
function revive(){ S.retries=(S.retries|0)+1; /* p2m4: ikinci şans 3. yıldızı (tekrar yok) götürür */ S.revived=true; S.failed=false; S.nightOn=true; S.failPaid=false; /* yenilgi sayacı düşmez (tekrar deneme zorlaşmaz); ikinci kayıp da tacını öder */ const bn=S.wave===WAVES; S.gateHp=D.gateMax()*(bn?1:0.8); { const sn=S.nightSnap; if(sn&&sn.level===S.level&&sn.wave===S.wave&&typeof sn.minGate==='number') S.minGate=sn.minGate; } /* FX1: Gece tekrarı gibi: yıldız için sur gece başındaki değere döner (eskiden 0.01 → en çok 1 yıldız) */ gateWarned=0;
  for(const e of enemies){ if(e.dead||e.hold||(e.pre&&e.pre.length)) continue; const P=ROADS[e.side], d0=SD[e.side], big=e.boss||e.kind==='ram'; const i=big?2:3, k=big?Math.random()*0.3:Math.random()*0.6; const x=lerp(P[i][0],P[i+1][0],k)+d0.t[0]*e.off, z=lerp(P[i][1],P[i+1][1],k)+d0.t[1]*e.off; e.g.position.set(x,0,z); e.wp=i+1; e.stuckT=0; e.rage=0; e.atkCd=1; }
  shieldT=8; runOver=false; celebrate(player.g.position.clone(),1); banner(T('Sur onarıldı!','Walls fixed!'),T('🛡️ 8 sn kalkan · düşmanlar geri püskürtüldü','🛡️ 8 s shield · enemies pushed back'),'day'); save(); }
// ---------- Krallık: Sefer (haritalar) | Yurt (kalıcı ağaç, Kraliyet Sandığı, kupalar, defter) ----------
/* p2m5: UPG/UPC/upMax/upCost p1'de (D.* kancaları açılışta okur). Taç yetiyorsa ya da Kraliyet Sandığı doluysa 👑 düğmesi nabız atar */
function upAfford(){ const m=S.meta; if(!m) return false; return Object.keys(UPG).some(k=>(m.crowns||0)>=upCost(k,mu(k))); }
function kingUp(){ return upAfford()||rcState().full; }
function buyUp(k){ const lv=mu(k), cost=upCost(k,lv); if(!(cost<=S.meta.crowns)) return false; S.meta.crowns-=cost; S.meta.up[k]=lv+1; S.meta.upB=1; stat('ups'); save(); return true; }
const dayKey=()=>{ const d=new Date(); return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate(); };
function dailyGift(){ const k=dayKey(); if(S.meta.dailyDate===k) return 0; const y=new Date(); y.setDate(y.getDate()-1); const yk=y.getFullYear()+'-'+(y.getMonth()+1)+'-'+y.getDate(); S.meta.streak=(S.meta.dailyDate===yk)?(S.meta.streak||0)+1:1; S.meta.dailyDate=k; const g=giftOf(S.meta.streak); S.meta.crowns+=g; save(); return g; }
// v39: yarına sebep: günde bir kez, ~8 dk oynayan oyuncuya gece bitince yarınki hediye ve yeni görevler hatırlatılır (engellemez, sıraya girer)
function tmrwHint0(){ try{ if(!S.meta||((CG.playSec||0)<240&&S.wave<3)) return ''; const k=dayKey(); if(S.meta.tmrwDate===k) return ''; S.meta.tmrwDate=k; const nx=S.meta.dailyDate===k?(S.meta.streak||0)+1:1, g=giftOf(nx); save(); return T(`🎁 Yarın gel: +${g} 👑 hediye · yeni görevler`,`🎁 Come back tomorrow: +${g} 👑 gift · new quests`); }catch(e){ return ''; } } /* v40: 4 dk ya da 2 gece sonra; gece bitti afişinin altına yazılır (bildirim sırasında kaybolmaz) */
const GIFT=[2,3,4,5,6,8,10]; function giftOf(n){ return GIFT[Math.max(0,Math.min(GIFT.length-1,(n||1)-1))]; } /* FX2: 7 günlük seri (eski 2-4 taç); dönüşte kartla verilir */
/* p2m5: Kraliyet Sandığı: gerçek zamanla (oyunda da, yokken de) dolar; 45 dk'da 1 taç, 8 saatte dolar (10 taç) + dolunca bir hazır güç kartı (meta.nextCard → sonraki harita).
   meta.rcT = dolmaya başladığı an. İlk kez: son görülme (eski oyuncu dönüşte dolu bulur) ya da şimdi. Saat geri alınırsa sıfırdan başlar */
const RC_CAP=8*3600e3, RC_STEP=45*60e3;
function rcT(){ const m=S.meta, now=Date.now(); if(!(m.rcT>0)||m.rcT>now+60e3) m.rcT=(S.lastSeen>0&&S.lastSeen<=now)?S.lastSeen:now; return m.rcT; }
function rcState(now){ now=now||Date.now(); const el=Math.max(0,Math.min(RC_CAP,now-rcT())); return {el,pct:el/RC_CAP,cr:Math.floor(el/RC_STEP),full:el>=RC_CAP,left:RC_CAP-el,next:RC_STEP-(el%RC_STEP)}; }
function rcClaim(){ const r=rcState(); if(r.cr<=0) return null; S.meta.crowns+=r.cr; let card=0; if(r.full){ S.meta.nextCard=(S.meta.nextCard||0)+1; card=1; S.meta.rcT=Date.now(); } else S.meta.rcT=Date.now()-(r.el%RC_STEP); stat('rc',r.cr); save(); return {cr:r.cr,card}; } /* artan dakikalar bir sonraki taca sayılır */
const hm=ms=>{ const m=Math.max(1,Math.ceil(ms/60000)), h=Math.floor(m/60); return h?T(`${h} sa ${m%60} dk`,`${h}h ${m%60}m`):T(`${m} dk`,`${m}m`); };
function rcHtml(){ const r=rcState(); return `<div class="rchest${r.full?' full':''}"><div class="rch"><i>${r.full?'🎁':'🧰'}</i><div><b>${T('Kraliyet Sandığı','Royal Chest')}</b><small>${r.full?T('Dolu! Taçlarını al','Full! Claim your crowns'):T(`${hm(r.left)} sonra dolu · 45 dk'da 1 👑`,`Full in ${hm(r.left)} · 1 👑 per 45 min`)}</small></div><button id="rcGet" ${r.cr>0?'':'disabled'}>${r.cr>0?`${T('AL','CLAIM')} 👑 +${r.cr}${r.full?' · 🃏':''}`:T(`${hm(r.next)}`,`${hm(r.next)}`)}</button></div><div class="prog"><i style="width:${Math.round(r.pct*100)}%"></i><span>${Math.round(r.pct*100)}%${r.full?' · 🃏 '+T('kart hediye','bonus card'):''}</span></div></div>`; }
const BR=[['eco','🪓',T('Ekonomi','Economy')],['def','🛡️',T('Savunma','Defense')],['hero','🏹',T('Kahraman','Hero')]];
/* v44: güçlendirmenin somut etkisi: şimdi → sonraki seviye (ör. "Kahraman hasarı 30→34") */
function upFx(k,lv){ const f=(a,b,u)=>`${a}${u||''}→${b}${u||''}`, r1=x=>Math.round(x*10)/10, n=lv+1;
  switch(k){ case 'gold': return T(`Başlangıç altını +${40*lv}→+${40*n}`,`Start gold +${40*lv}→+${40*n}`); case 'saddle': return T(`Taşıma ${f(40+10*lv,40+10*n)}`,`Carry ${f(40+10*lv,40+10*n)}`); case 'magnet': return T(`Toplama mesafesi +%${15*lv}→+%${15*n}`,`Pickup range +${15*lv}%→+${15*n}%`);
    case 'wall': return T(`Sur canı (Sv1) ${f(Math.round(270*(1+0.08*lv)),Math.round(270*(1+0.08*n)))}`,`Wall HP (Lv1) ${f(Math.round(270*(1+0.08*lv)),Math.round(270*(1+0.08*n)))}`); case 'arrow': return T(`Kule hasarı (Sv3) ${f(r1(11*(1+0.06*lv)),r1(11*(1+0.06*n)))}`,`Tower dmg (Lv3) ${f(r1(11*(1+0.06*lv)),r1(11*(1+0.06*n)))}`);
    case 'bow': { const b=HERO_K*heroScale(); return T(`Kahraman hasarı ${f(Math.round(b*(1+0.12*lv)),Math.round(b*(1+0.12*n)))}`,`Hero dmg ${f(Math.round(b*(1+0.12*lv)),Math.round(b*(1+0.12*n)))}`); } case 'quiver': return T(`Atış hızı +%${8*lv}→+%${8*n} · menzil +${r1(0.5*lv)}→+${r1(0.5*n)}`,`Fire rate +${8*lv}%→+${8*n}% · range +${r1(0.5*lv)}→+${r1(0.5*n)}`); }
  return ''; }
function upSummary(){ const a=[], p=(k,tr,en,x)=>{ const l=mu(k); if(l>0) a.push(T(`${tr} +${x(l)}`,`${en} +${x(l)}`)); }; p('arrow','Kuleler','Towers',l=>LANG==='tr'?`%${6*l}`:`${6*l}%`); p('wall','Sur','Walls',l=>LANG==='tr'?`%${8*l}`:`${8*l}%`); p('bow','Kahraman','Hero',l=>LANG==='tr'?`%${12*l}`:`${12*l}%`); if(mu('gold')>0) a.push(T(`+${40*mu('gold')} altın`,`+${40*mu('gold')} gold`)); return a.length?T('Krallık: ','Kingdom: ')+a.join(' · '):''; }
const UP_PRI=['arrow','wall','bow','gold','quiver','outpost','saddle','magnet','scout']; function upBest(){ let best=null, bl=1e9; for(const k of UP_PRI){ if(!UPG[k]) continue; const lv=mu(k); if(lv>=upMax(k)) continue; const c=upCost(k,lv); if(c<bl){ bl=c; best=k; } } return best; } /* v44: "En iyi sonraki": en ucuz sıradaki seviye, değer sırasına göre (kule > sur > kahraman > ...) */
function treeHtml(){ const m=S.meta, bestK=upBest(); return `<div class="tree">${BR.map(([b,ic,bn])=>`<div class="br"><h3>${ic} ${bn}</h3>${Object.keys(UPG).filter(k=>UPG[k].b===b).map(k=>{ const u=UPG[k], lv=mu(k), mx=u.mx, max=lv>=mx, cost=upCost(k,lv); const d=u.lv?(u.lv[Math.min(lv,mx-1)]):(max?u.d:(upFx(k,lv)||u.d)); return `<div class="upr${max?' max':''}${k===bestK?' best':''}"><i>${u.i}</i><div><b><span class="un">${u.n}</span>${k===bestK?`<em class="bestTag">★ ${T('En iyi sonraki','Best next')}</em>`:''}<span class="pips">${Array.from({length:mx},(_,i)=>`<em class="${i<lv?'on':''}"></em>`).join('')}</span></b><small>${max&&u.lv?T('Hepsi açık','All unlocked'):d}</small></div><button data-u="${k}" ${max||m.crowns<cost?'disabled':''}>${max?T('Tam','Max'):'👑 '+cost}</button></div>`; }).join('')}</div>`).join('')}</div>`; }
function trophyHtml(){ const m=S.meta, tr=m.troph||{}; let full=0; const it=[]; for(let L=1;L<=LEVELS;L++){ const p=Math.min(3,tr[L]|0), s3=smOf(L)===7, open=L<=m.unlocked; if(p>=3) full++; it.push(`<div class="tp${p>=3?' gold':''}${open?'':' no'}" title="${mapName(L)}"><i>${p>=3?'🏆':open?'🏆':'🔒'}</i><b>${L}</b><small>${p>=3?'✓':p+'/3'}</small>${s3?'<em>★</em>':''}</div>`); } const dt=m.dtro|0; return `<h3 class="bkh">🏆 ${T('Kupalar','Trophies')} · ${full}/${LEVELS}${dt?` · 🎯 ${dt}`:''}</h3><p class="ksub">${T('Patron sandığından 3 parça topla: kupa tamamlanınca +5 👑. ★ = haritada 3 yıldız.','Collect 3 pieces from boss chests: a finished trophy gives +5 👑. ★ = 3 stars on that map.')}</p><div class="troph">${it.join('')}</div>`; }
