  const selHere=(sel===S.level&&!S.won&&S.mode!=='daily'&&sel<=LEVELS)||(sel===LEVELS+1&&S.level>LEVELS); /* v44: ayrıntıda zaten "Devam et" varsa üstteki ikinci Devam düğmesi yok; biten harita/meydan okuma için Devam yok */
